/** Wire types, re-exported from the generated OpenAPI schema.
 *
 * `web/src/api/schema.d.ts` is generated by `make types` and gated by
 * `make lint-generated`, so these cannot drift from the API. Restating them
 * here by hand is how the two clients would start disagreeing about what a
 * `Card` is -- the exact thing keeping the extension in this repo is meant to
 * prevent.
 */

import type { components } from '../../../web/src/api/schema'

export type Card = components['schemas']['Card']
export type TextRun = components['schemas']['TextRun']
export type CardBatchResponse = components['schemas']['CardBatchResponse']

/** Contract C3's run kinds. Present from day one, all three. */
export type RunKind = 'entity' | 'glossary' | 'undefined'

/** The extension's site catalog. `match` is built and validated server-side --
 * it goes straight into `chrome.permissions.request`, so it is minted in the
 * same place it is checked rather than reassembled here from `domain`. */
export type AnnotatableSite = components['schemas']['AnnotatableSite']

export type AnnotateBlock = components['schemas']['AnnotateBlockOut']
export type AnnotateRequest = components['schemas']['AnnotateRequest']
export type AnnotateResponse = components['schemas']['AnnotateResponse']
